updateCartQuantity(interaction, action) {
  try {
    if (action === 'add') {
      this.quantity += 1;
    } else if (action === 'remove') {
      this.quantity -= 1;
      if (this.quantity <= 0) {
        this.quantity = 1;
        await interaction.reply({ embeds: [new EmbedBuilder().setDescription('❌ | Você não pode diminuir mais.')]], ephemeral: true });
        return;
      }
    }

    await Cart.findOneAndUpdate(
      { channelId: this.channel.id },
      { quantity: this.quantity },
      { new: true }
    );

    await interaction.update(this.cratePlanItens());

    // Reset inactivity timer
    this.setInactivityTimer(() => this.handleInactivity(), this.inactivityDelay);
  } catch (error) {
    console.error('Error updating cart quantity:', error);
  }
}
