    private Dictionary<Character, DateTime> pauseTimes = new Dictionary<Character, DateTime>();
    private Dictionary<Character, bool> isPaused = new Dictionary<Character, bool>();

    void Update()
    {
        // --- Input ---
        if (Input.GetKeyDown("SuperPause"))
        {
            // Assume que o jogador está controlando o personagem atual
            var charToPause = selectedCharacter;
            isPaused[charToPause] = true;
        }
        else if (Input.GetKeyUp("SuperPause"))
        {
            isPaused[charToPause] = false;
        }

        // --- Detectar quando sair da pause ---
        foreach (var kvp in pauseTimes)
        {
            if (!kvp.Value.IsPaused && (DateTime.Now - kvp.Key.StartTime).TotalSeconds > pauseDuration)
            {
                // Ativa habilidade no timestamp salvo
                ApplySpecificAbility(kvp.Key, kvp.Key.StartTime);
                pauseTimes.Remove(kvp.Key);
